{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Puzzle2d Optional Text Diagnostic Cases",
  "type": "object",
  "additionalProperties": false,
  "required": ["cases"],
  "properties": {
    "cases": {
      "type": "array",
      "minItems": 6,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["role", "id", "before", "next", "target", "operationIndex", "expected"],
        "properties": {
          "role": {"enum": ["nodeIcon", "regionLabel"]},
          "id": {"type": "string"},
          "before": {"type": ["string", "null"]},
          "next": {"type": ["string", "null"]},
          "target": {"type": "boolean"},
          "operationIndex": {"type": ["integer", "null"], "minimum": 0, "maximum": 4294967295},
          "expected": {
            "anyOf": [
              {"type": "null"},
              {
                "type": "object",
                "additionalProperties": false,
                "required": ["level", "code", "body", "targets", "fragmentKinds"],
                "properties": {
                  "level": {"enum": ["warning", "error"]},
                  "code": {"enum": ["mutation.no-op", "mutation.target-missing"]},
                  "body": {"type": "string"},
                  "targets": {"type": "array", "minItems": 1, "maxItems": 1, "items": {"type": "string"}},
                  "fragmentKinds": {"type": "array", "items": {"enum": ["static", "text"]}}
                }
              }
            ]
          }
        }
      }
    }
  }
}

