import {expect,test} from "bun:test";
import {Database} from "bun:sqlite";
import Ajv from "ajv";
import {existsSync,readFileSync} from "node:fs";
import {resolve} from "node:path";
import fixture from "../🧫️fixtures/🔣️.json";
import schema from "../🧬️schema/🔣️.json";

test("Puzzle2d optional text diagnostics expose borrowed raw ID fragments and exact severity",()=>{
 expect(new Ajv({strict:true}).compile(schema)(fixture)).toBe(true);
 const db=new Database(":memory:");db.exec("CREATE TABLE target(ordinal INTEGER PRIMARY KEY,id TEXT,value TEXT)");
 try{for(const row of fixture.cases){
  db.exec("DELETE FROM target");
  if(row.target){db.query("INSERT INTO target VALUES(0,?,?)").run(row.id,row.before);db.query("INSERT INTO target VALUES(1,?,?)").run(row.id,"untouched duplicate");}
  const result=db.query("SELECT CASE WHEN value IS ? THEN 'noOp' ELSE 'changed' END AS disposition FROM target WHERE id=? ORDER BY ordinal LIMIT 1").get(row.next,row.id)as {disposition:string}|null;
  const disposition=result?.disposition??"targetMissing",prefix=row.role==="nodeIcon"?"node \"":"target region \"";
  const fragments=disposition==="noOp"?[{kind:"static",text:"no changes to apply"}]:[{kind:"static",text:prefix},{kind:"text",text:row.id},{kind:"static",text:"\" not found"}];
  const actual=disposition==="changed"?null:{level:disposition==="noOp"?"warning":"error",code:disposition==="noOp"?"mutation.no-op":"mutation.target-missing",body:fragments.map(value=>value.text).join(""),targets:[row.id],fragmentKinds:fragments.map(value=>value.kind)};
  expect(actual).toEqual(row.expected);
  if(actual){const decoded=new TextDecoder().decode(new TextEncoder().encode(actual.body));expect(decoded).toBe(row.expected!.body);expect(JSON.parse(JSON.stringify(actual))).toEqual(row.expected);}
  if(row.target)expect((db.query("SELECT value FROM target WHERE ordinal=1").get()as {value:string}).value).toBe("untouched duplicate");
 }}finally{db.close()}
 console.log("[DEBUG] six SQLite first-owner diagnostics preserve raw quotes/NUL/Unicode, exact severity and untouched duplicate");
 const path=resolve(import.meta.dir,"../🦀️.rs");expect(existsSync(path)).toBe(true);
 const source=readFileSync(path,"utf8");
 for(const marker of["Puzzle2dTextDiagnosticSource","ArtifactMessageSource","ArtifactMessageFragment::Text","Puzzle2dTextDisposition::TargetMissing","operation_index"])expect(source).toContain(marker);
 expect(source).not.toMatch(/format!|\.to_string_owner\(|ArtifactMessageFragment::JsonQuoted|\.clone\(/u);
});

import { test, expect } from "bun:test";
import { readFileSync } from "node:fs";
import Ajv from "ajv/dist/2020.js";
import { BoxGeometry, Triangle, Vector3 } from "three";

/** 🎟️ Independent schema and geometry oracle for the original retained tessellation laws. */
test("original tessellation grants and unit-box parity agree with Ajv and Three", () => {
  const fixture=JSON.parse(readFileSync(new URL("../../🧫️fixtures/🎟️ownership/🔣️.json",import.meta.url),"utf8"));
  const schema=JSON.parse(readFileSync(new URL("../../🧫️fixtures/🎟️ownership/🧬️schema.json",import.meta.url),"utf8"));
  expect(new Ajv({strict:true}).compile(schema)(fixture)).toBe(true);
  const geometry=new BoxGeometry(1,1,1);const position=geometry.getAttribute("position");const index=geometry.getIndex()!;
  let area=0,volume=0;const corners:[Vector3,Vector3,Vector3]=[new Vector3(),new Vector3(),new Vector3()];
  for(let cursor=0;cursor<index.count;cursor+=3){corners.forEach((point,offset)=>point.fromBufferAttribute(position,index.getX(cursor+offset)));area+=new Triangle(...corners).getArea();volume+=corners[0].dot(corners[1].clone().cross(corners[2]))/6;}
  expect(area).toBe(fixture.box.area);expect(Math.abs(volume)).toBeCloseTo(fixture.box.volume,12);expect(index.count/3).toBe(fixture.box.triangles);geometry.dispose();
  console.log("[DEBUG] Original tessellation neutral ownership fixture: Ajv schema admitted; independent Three area=6 volume=1 triangles=12");
});

/** 🧵️ Portable JSON, UTF8 and RFC6902 independently define borrowed diagnostic composition. */
import {expect, test} from "bun:test";
import {readFileSync} from "node:fs";
import Ajv from "ajv";
import {applyPatch} from "fast-json-patch";

const law=JSON.parse(readFileSync(new URL("../🧫️fixtures/🔣️.json",import.meta.url),"utf8"));
const bytes=(value:string)=>Buffer.byteLength(value,"utf8");

test("🧵️ neutral borrowed diagnostic rows satisfy their authored schema",()=>{
  const validate=new Ajv({allErrors:true,strict:true}).compile(law.schema);
  for(const row of law.cases){expect(validate(row),JSON.stringify(validate.errors)).toBe(true);expect(bytes(row.code)).toBeLessThanOrEqual(law.maximumCodeBytes);}
  expect(validate({...law.cases[0],limit:4097})).toBe(false);
  expect(validate({...law.cases[0],unknown:true})).toBe(false);
});

test("🧵️ borrowed diagnostic text agrees with JSON quoting, UTF8 prefixes and independent JSON Patch",()=>{
  for(const row of law.cases){
    const targets=row.targets.map((target:any)=>target.text.repeat(target.repeat));
    let remaining=row.limit-law.messageOwnerBytes-bytes(row.code);
    const targetIndices:number[]=[];
    targets.forEach((target:string,index:number)=>{const demand=law.targetOwnerBytes+bytes(target);if(demand<=remaining){targetIndices.push(index);remaining-=demand;}});
